from collections import Counter

class Solution:
    def customSortString(self, order: str, s: str) -> str:
        count = Counter(s)
        res = []
        for ch in order:
            if ch in count:
                res.append(ch * count[ch])
                del count[ch]
        for ch, cnt in count.items():
            res.append(ch * cnt)
        return "".join(res)

class Solution {
public:
    string customSortString(string order, string s) {
        vector<int> count(26, 0);
        for (char ch : s) count[ch - 'a']++;
        string res = "";
        for (char ch : order) {
            while (count[ch - 'a'] > 0) {
                res += ch;
                count[ch - 'a']--;
            }
        }
        for (int i = 0; i < 26; i++) {
            while (count[i] > 0) {
                res += (char)('a' + i);
                count[i]--;
            }
        }
        return res;
    }
};

class Solution {
    public String customSortString(String order, String s) {
        int[] count = new int[26];
        for (int i = 0; i < s.length(); i++) {
            count[s.charAt(i) - 'a']++;
        }
        StringBuilder res = new StringBuilder();
        for (int i = 0; i < order.length(); i++) {
            char ch = order.charAt(i);
            while (count[ch - 'a'] > 0) {
                res.append(ch);
                count[ch - 'a']--;
            }
        }
        for (int i = 0; i < 26; i++) {
            while (count[i] > 0) {
                res.append((char)('a' + i));
                count[i]--;
            }
        }
        return res.toString();
    }
}

var customSortString = function(order, s) {
    const count = new Array(26).fill(0);
    for (let i = 0; i < s.length; i++) {
        count[s.charCodeAt(i) - 97]++;
    }
    let res = "";
    for (let i = 0; i < order.length; i++) {
        const idx = order.charCodeAt(i) - 97;
        while (count[idx] > 0) {
            res += order[i];
            count[idx]--;
        }
    }
    for (let i = 0; i < 26; i++) {
        while (count[i] > 0) {
            res += String.fromCharCode(97 + i);
            count[i]--;
        }
    }
    return res;
};
